class Personagem:
    def __init__(self, nome: str, vida: int, ataque: int):
        self.nome = nome
        self.vida = max(0, vida)
        self.ataque = ataque

    def receber_dano(self, quantidade: int):
        self.vida = max(0, self.vida - quantidade)

class Paladino(Personagem):
    def __init__(self, nome: str, vida: int, ataque: int, fe: int):
        # Inicializa a classe herdada:
        super().__init__(nome, vida, ataque)
        self.fe = fe

    def curar(self, quantidade: int):
        if self.fe >= 10:
            self.fe -= 10
            self.vida += quantidade

