function configurarBotaoEquipar() {
  const botao = document.querySelector("#btn-equipar");
  const displayArma = document.querySelector("#status-arma");

  // Verificação defensiva de existência do nó:
  if (!botao || !displayArma) return;

  botao.addEventListener("click", () => {
    displayArma.textContent = "Espada Vorpal Equipada!";
    displayArma.classList.add("arma-ativa");

    // Evita múltiplos cliques simultâneos:
    botao.disabled = true;
    botao.textContent = "Equipado com Sucesso ✓";
  });
}

async function buscarMissoesDaGuilda(endpoint) {
  try {
    const resposta = await fetch(endpoint);

    // Verificação OBRIGATÓRIA de status HTTP 2xx:
    if (!resposta.ok) {
      throw new Error(`Erro da Guilda: Código HTTP ${resposta.status}`);
    }

    const dados = await resposta.json();
    return dados.sort((a, b) => b.poder - a.poder);
  } catch (erro) {
    console.error("[GUILDA_API_ERRO]", erro.message);
    throw erro; // Repassa para tratamento visual na UI
  }
}

